CREATE FUNCTION public.set_member_roles(target uuid,new_roles public.app_role[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores podem gerenciar funções'; END IF; PERFORM pg_advisory_xact_lock(701111); IF cardinality(new_roles)<1 THEN RAISE EXCEPTION 'Selecione pelo menos uma função'; END IF; IF public.has_role(target,'admin') AND NOT ('admin'=ANY(new_roles)) AND (SELECT count(*) FROM public.user_roles WHERE role='admin')<=1 THEN RAISE EXCEPTION 'A equipe precisa manter pelo menos um administrador'; END IF; DELETE FROM public.user_roles WHERE user_id=target; INSERT INTO public.user_roles(user_id,role) SELECT target,unnest(new_roles) ON CONFLICT DO NOTHING; INSERT INTO public.activity_log(actor_id,entity_type,entity_id,action) VALUES(auth.uid(),'user_roles',target,'UPDATE'); END $$;
REVOKE ALL ON FUNCTION public.set_member_roles(uuid,public.app_role[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_member_roles(uuid,public.app_role[]) TO authenticated;
CREATE FUNCTION public.append_creative_version(target_item uuid,target_file uuid) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE next_version integer; version_uuid uuid; BEGIN PERFORM 1 FROM public.demand_items WHERE id=target_item FOR UPDATE; SELECT id INTO version_uuid FROM public.creative_versions WHERE item_id=target_item AND file_id=target_file; IF version_uuid IS NOT NULL THEN RETURN version_uuid; END IF; SELECT coalesce(max(version),0)+1 INTO next_version FROM public.creative_versions WHERE item_id=target_item; INSERT INTO public.creative_versions(item_id,file_id,version) VALUES(target_item,target_file,next_version) RETURNING id INTO version_uuid; RETURN version_uuid; END $$;
REVOKE ALL ON FUNCTION public.append_creative_version(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.append_creative_version(uuid,uuid) TO authenticated;
CREATE FUNCTION public.validate_item_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (SELECT kind FROM public.demands WHERE id=new.demand_id)='individual' AND EXISTS(SELECT 1 FROM public.demand_items WHERE demand_id=new.demand_id) THEN RAISE EXCEPTION 'Uma demanda individual deve conter apenas um criativo'; END IF; IF new.assigned_to IS NOT NULL AND NOT public.has_role(new.assigned_to,'editor') THEN RAISE EXCEPTION 'O responsável deve possuir a função Editor'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_item_insert BEFORE INSERT ON public.demand_items FOR EACH ROW EXECUTE FUNCTION public.validate_item_insert();
CREATE FUNCTION public.validate_file_metadata() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF lower(split_part(reverse(new.name),'.',1)) NOT IN ('4pm','vom','gpj','gepj','gnp','pbew','fdp','txt','xcod') THEN RAISE EXCEPTION 'Formato de arquivo não permitido'; END IF; IF new.purpose='final' AND new.item_id IS NULL THEN RAISE EXCEPTION 'Arquivo final deve pertencer a um criativo'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_file_metadata BEFORE INSERT ON public.files FOR EACH ROW EXECUTE FUNCTION public.validate_file_metadata();